/* ---------- UI helpers ---------- */
const PILL={Operational:'ok','Needs Greasing':'warn','In Repair':'rep',Overdue:'bad',Running:'ok',Idle:'mute',Down:'bad',Scheduled:'info','In progress':'rep',Done:'ok',Pending:'warn',Approved:'ok',Rejected:'bad',Closed:'mute',Open:'warn',Pass:'ok',Fail:'bad',Compliant:'ok','Action needed':'warn',Breach:'bad',Inbound:'info',Outbound:'ok'};
const pill=s=>`<span class="pill ${PILL[s]||'mute'}">${esc(s)}</span>`;
const tag=m=>`<span class="tag">${esc(m.code)}</span>`;
const pq=r=>r.pending?`<span class="q" title="Saved on this device, waiting to sync">queued</span>`:'';
const table=(heads,rows,empty='Nothing logged yet.')=>`<div class="tw"><table class="t"><thead><tr>${heads.map(h=>`<th${h[0]==='#'?' class="num"':''}>${h.replace(/^#/,'')}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${heads.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`;
const tile=(k,v,s,c='',icon='',nav='')=>`<${nav?`button data-a="nav" data-tab="${nav.split('/')[0]}" data-sub="${nav.split('/')[1]||''}"`:'div'} class="tile ${c}"><span class="k">${icon?ic(icon):''}${k}</span><span class="v">${v}</span><span class="s">${s}</span></${nav?'button':'div'}>`;
const head=(t,p,acts='')=>`<div class="ph"><div><h1>${t}</h1><p>${p}</p></div><div class="acts">${acts}</div></div>`;
const btn=(a,label,icon,cls='',data='')=>`<button class="btn ${cls}" data-a="${a}" ${data}>${icon?ic(icon):''}${label}</button>`;
function niceMax(v){if(v<=0)return 1;const p=Math.pow(10,Math.floor(Math.log10(v))),f=v/p;return[1,1.5,2,2.5,3,4,5,6,8,10].find(x=>x>=f)*p}
function barChart(items,o={}){
 const mx=niceMax(Math.max(...items.map(i=>i.v),...(o.line||[0]))*1.04),n=items.length;
 const pts=(o.line||[]).map((v,i)=>`${((i+.5)/n*100).toFixed(2)},${(100-v/mx*100).toFixed(2)}`).join(' ');
 return`<div class="chart"><div class="yax"><span>${fN(mx)}</span><span>${fN(mx/2)}</span><span>0</span></div><div class="plot"><div class="bars">${items.map((it,i)=>`<div class="bcol" title="${esc(it.label)}: ${fN(it.v,o.dp||0)} ${o.unit||''}"><div class="bar${i===n-1&&o.partial?' part':''}" style="height:${(it.v/mx*100).toFixed(1)}%"></div></div>`).join('')}</div>${pts?`<svg class="ln" viewBox="0 0 100 100" preserveAspectRatio="none"><polyline points="${pts}" fill="none" vector-effect="non-scaling-stroke"/></svg>`:''}</div><div class="xax">${items.map((it,i)=>`<span>${i%2===(n-1)%2?esc(it.short):''}</span>`).join('')}</div><div class="leg"><span><i class="sw b"></i>${o.barLabel}</span>${o.lineLabel?`<span><i class="sw l"></i>${o.lineLabel}</span>`:''}${o.partial?'<span><i class="sw p"></i>Today so far</span>':''}</div></div>`}
function meter(label,actual,target,unit='t'){const pct=target?actual/target*100:0,c=pct>=100?'ok':pct>=60?'warn':'bad',mx=Math.max(target*1.25,actual,1);
 return`<div class="meter"><div class="mh"><b>${esc(label)}</b><span class="mono">${fN(actual,1)} / ${fN(target)} ${unit}<em class="${c}">${fN(pct)}%</em></span></div><div class="mt ${c}"><div class="mf" style="width:${(actual/mx*100).toFixed(1)}%"></div><div class="mk" style="left:${(target/mx*100).toFixed(1)}%" title="Target ${fN(target)} ${unit}"></div></div></div>`}
const hbar=(pct,c)=>`<div class="hbar ${c}"><i style="width:${clamp(pct,0,100).toFixed(0)}%"></i></div>`;
const ring=(pct,c,txt,size=64)=>`<span class="ring ${c}" style="width:${size}px;height:${size}px" role="img" aria-label="${esc(txt)}"><svg viewBox="0 0 36 36"><circle class="rt" cx="18" cy="18" r="15.9" fill="none"/><circle class="rv" cx="18" cy="18" r="15.9" fill="none" pathLength="100" stroke-dasharray="${clamp(pct,0,100).toFixed(1)} 100" transform="rotate(-90 18 18)"/></svg><b style="font-size:${Math.round(size*.25)}px">${txt}</b></span>`;
function spark(vals){const mx=Math.max(...vals,1),mn=Math.min(...vals)*.9,n=vals.length,p=vals.map((x,i)=>`${(i/(n-1)*100).toFixed(1)},${(30-(x-mn)/(mx-mn||1)*26).toFixed(1)}`);
 return`<svg class="spark" viewBox="0 0 100 32" preserveAspectRatio="none" aria-hidden="true"><polygon points="0,32 ${p.join(' ')} 100,32" fill="currentColor" fill-opacity=".14"/><polyline points="${p.join(' ')}" fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`}
function qr(text,size=92){let h=2166136261;for(const c of text){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}const r=rng(h),n=21;let d='';
 const fnd=(x,y,a,b)=>{const dx=x-a,dy=y-b;if(dx<-1||dx>7||dy<-1||dy>7)return null;if(dx<0||dx>6||dy<0||dy>6)return 0;return dx===0||dx===6||dy===0||dy===6||(dx>=2&&dx<=4&&dy>=2&&dy<=4)?1:0};
 for(let y=0;y<n;y++)for(let x=0;x<n;x++){let v=fnd(x,y,0,0);if(v===null)v=fnd(x,y,14,0);if(v===null)v=fnd(x,y,0,14);if(v===null)v=r()<.5?1:0;if(v)d+=`M${x} ${y}h1v1h-1z`}
 return`<svg class="qr" width="${size}" height="${size}" viewBox="-1 -1 23 23" role="img" aria-label="QR tag for ${esc(text)}"><path d="${d}" fill="#0a0d0f"/></svg>`}

/* ---------- state changes ---------- */
const COLS=['deliveries','usage','maint','production','tickets','tasks','checks','permits','envlogs','incidents'];
function add(col,rec,msg){rec.id=uid();rec.site=rec.site||S.ui.site;if(!S.ui.online){rec.pending=true;S.queue++}S[col].unshift(rec);save();toast((msg||'Saved')+(S.ui.online?'':' on this device. It will sync when you are back online.'));return rec}
let toastT;function toast(m){const t=$('#toast');t.innerHTML=ic('circle-check')+`<span>${esc(m)}</span>`;t.hidden=false;icons();clearTimeout(toastT);toastT=setTimeout(()=>t.hidden=true,3400)}
let syncing=false;
function setNet(on){if(S.ui.online===on)return;S.ui.online=on;save();
 if(on&&S.queue){syncing=true;render();setTimeout(()=>{const n=S.queue;COLS.forEach(c=>S[c].forEach(r=>delete r.pending));S.queue=0;S.lastSync=Date.now();syncing=false;save();render();toast(`${n} record${n>1?'s':''} synced`)},1700)}
 else{if(on)S.lastSync=Date.now();render()}}

/* ---------- modal + forms ---------- */
let formCb=null;
function modal(html){const m=$('#modal');m.innerHTML=`<div class="mbox" role="dialog" aria-modal="true">${html}</div>`;m.hidden=false;icons();const f=m.querySelector('form input,form select,form textarea');if(f)f.focus()}
function closeModal(){$('#modal').hidden=true;$('#modal').innerHTML='';formCb=null}
function fld(f){const id='f-'+f.name,req=f.req===false?'':' required';let c;
 if(f.type==='pf')return`<div class="pf wide"><span>${esc(f.label)}</span><div class="seg"><label><input type="radio" name="${f.name}" value="Pass" id="${id}-p" required><b class="ok">Pass</b></label><label><input type="radio" name="${f.name}" value="Fail" id="${id}-f"><b class="bad">Fail</b></label></div></div>`;
 if(f.type==='select')c=`<select id="${id}" name="${f.name}"${req}>${f.options.map(o=>{const[v,l]=Array.isArray(o)?o:[o,o];return`<option value="${esc(v)}"${String(v)===String(f.value)?' selected':''}>${esc(l)}</option>`}).join('')}</select>`;
 else if(f.type==='textarea')c=`<textarea id="${id}" name="${f.name}" rows="3"${req} placeholder="${esc(f.ph||'')}">${esc(f.value||'')}</textarea>`;
 else c=`<input id="${id}" name="${f.name}" type="${f.type||'text'}" value="${esc(f.value??'')}"${f.type==='number'?` step="${f.step||'any'}" min="${f.min??0}"`:''} placeholder="${esc(f.ph||'')}"${req}>`;
 return`<label class="fl${f.wide||f.type==='textarea'?' wide':''}" for="${id}"><span>${esc(f.label)}</span>${c}</label>`}
function openForm({title,icon,fields,submit='Save',intro,onSubmit}){formCb={fields,onSubmit};
 modal(`<h2>${ic(icon||'plus')}${esc(title)}<button type="button" class="btn sm x" data-a="closeModal" aria-label="Close">${ic('x')}</button></h2>${intro?`<p class="mute" style="margin:0">${intro}</p>`:''}<form id="mform"><div class="fg">${fields.map(fld).join('')}</div><div class="ma" style="margin-top:16px"><button type="button" class="btn" data-a="closeModal">Cancel</button><button class="btn pri">${ic('check')}${esc(submit)}</button></div></form>`)}
const mOpts=(f)=>here(S.machines).filter(f||(()=>true)).map(m=>[m.id,`${m.code} · ${m.name}`]);
const sOpts=()=>here(S.staff).map(p=>p.name);

/* ---------- navigation ---------- */
const TABS={overview:{l:'Command centre',i:'layout-dashboard'},diesel:{l:'Diesel',i:'fuel'},maint:{l:'Maintenance & predictive AI',i:'wrench'},prod:{l:'Production & weighbridge',i:'factory'},staff:{l:'Staff & voice log',i:'users',p:'staff'},ehs:{l:'Health, safety & environment',i:'hard-hat'},fleet:{l:'Equipment & IoT fleet',i:'radio-tower'},reports:{l:'Executive reports',i:'chart-column',p:'reports'}};
const SUBS={diesel:[['overview','Overview'],['deliveries','Deliveries'],['usage','Daily usage']],maint:[['schedule','Schedule'],['status','Machine status'],['ai','Predictive AI','predictive']],prod:[['output','Target vs actual'],['wb','Weighbridge','weighbridge'],['history','History']],staff:[['att','Attendance & shifts'],['tasks','Tasks'],['score','Team scorecards'],['chat','Voice & WhatsApp log']],ehs:[['fork','Forklift checks'],['permits','Permits to work'],['env','Environmental'],['inc','Incidents & near misses']],fleet:[['grid','Live fleet'],['zones','Yard zones'],['qr','QR scan']],reports:[['exec','Daily executive report'],['sites','Multi-site','multisite'],['rbac','Access control']]};
function curSub(tab){const l=SUBS[tab],s=S.ui.sub[tab],ok=l.find(x=>x[0]===s&&(!x[2]||can(x[2])));return ok?s:l.find(x=>!x[2]||can(x[2]))[0]}
const tabs=tab=>`<div class="tabs" role="tablist">${SUBS[tab].map(([id,l,p])=>`<button class="tab${curSub(tab)===id?' on':''}" role="tab" aria-selected="${curSub(tab)===id}" data-a="sub" data-tab="${tab}" data-sub="${id}"${p&&!can(p)?' disabled title="Not available for this role"':''}>${l}${p&&!can(p)?ic('lock'):''}</button>`).join('')}</div>`;
function icons(){if(window.lucide)try{lucide.createIcons()}catch(e){}}
function render(){
 if(TABS[S.ui.tab].p&&!can(TABS[S.ui.tab].p))S.ui.tab='overview';
 const st=siteStats(S.ui.site),att=attention(st).filter(a=>a.c==='bad').length;
 $('#nav').innerHTML=Object.entries(TABS).map(([id,t])=>{const lock=t.p&&!can(t.p);return`<button class="ni${S.ui.tab===id?' on':''}${lock?' lock':''}" data-a="nav" data-tab="${id}"${lock?' aria-disabled="true" title="Hidden for the '+S.ui.role+' role"':` title="${t.l}"`}>${ic(t.i)}<span>${t.l}</span>${lock?ic('lock','lk'):id==='overview'&&att?`<span class="bdg">${att}</span>`:''}</button>`}).join('');
 $('#sel-site').innerHTML=S.sites.map(s=>`<option value="${s.id}"${s.id===S.ui.site?' selected':''}>${s.name}</option>`).join('');
 $('#sel-role').innerHTML=ROLES.map(r=>`<option${r===S.ui.role?' selected':''}>${r}</option>`).join('');
 const nb=$('#btn-net');nb.className='stat'+(S.ui.online?'':' off');nb.innerHTML=S.ui.online?'<i class="dot"></i><span class="lg">Cloud synced · Offline ready</span><span class="sm">Synced</span>':`<i class="dot"></i><span class="lg">Offline · ${S.queue} queued on device</span><span class="sm">Offline · ${S.queue}</span>`;nb.title=(S.ui.online?`Last synced at ${hhmm(S.lastSync)}. `:'')+'Tap to simulate losing or regaining Wi-Fi';
 $('#avatar').textContent=S.ui.role.split(' ').map(w=>w[0]).join('').padEnd(2,S.ui.role[1]).toUpperCase().slice(0,2);$('#app').classList.toggle('mini',!!S.ui.mini);
 $('#banner').innerHTML=syncing?`<div class="bn sync">${ic('refresh-cw','spin')}Back in range. Syncing ${S.queue} cached record${S.queue>1?'s':''}…</div>`:S.ui.online?'':`<div class="bn off">${ic('wifi-off')}<span>Working offline. ${S.queue?`${S.queue} record${S.queue>1?'s':''} cached on this device.`:'Nothing waiting to sync.'} Keep logging: everything syncs when you are back in Wi-Fi range.</span></div>`;
 $('#view').innerHTML=`<div class="wrap">${V[S.ui.tab](st)}</div>`;
 icons();const ch=$('.chat');if(ch)ch.scrollTop=ch.scrollHeight}

/* ---------- views ---------- */
const V={};
V.overview=st=>{const ds=st.ds,at=attention(st),tp=st.tToday/st.targetDay*100,ph=DAYS.slice(0,13).map(d=>sum(here(S.production).filter(p=>p.date===d),p=>p.tonnes));
 return head('Command centre',`${st.name}, ${new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'})}. Signed in as ${S.ui.role}.`,can('reports')?btn('nav','Generate daily report','sparkles','pri','data-tab="reports" data-sub="exec"'):'')+
 `<div class="grid g-6">${tile('Output today',`${fN(st.tToday,1)} <small>/ ${fN(st.targetDay)} t</small>`,`${fN(tp)}% of daily target`+spark(ph),tp>=100?'ok':tp>=55?'warn':'bad','factory','prod/output')}
 ${tile('Diesel in tank',`${fN(ds.stock)} <small>L</small>`,`${fN(ds.cover,1)} days of cover at ${fN(ds.avg7)} L/day`+spark(ds.daily.slice(0,13).map(x=>x.v)),ds.cover<5?'bad':ds.cover<10?'warn':'ok','fuel','diesel/overview')}
 ${tile('Fleet available',`${st.nMach-st.inRepair.length} <small>/ ${st.nMach}</small>`,`${st.inRepair.length} in repair, ${st.overdue.length} overdue`,st.inRepair.length?'bad':st.overdue.length?'warn':'ok','radio-tower','fleet/grid')}
 ${tile('Predictive alerts',st.alerts.length,st.alerts[0]?`Highest: ${st.alerts[0].m.code} at ${st.alerts[0].a.risk}%`:'No machine above the alert line',st.alerts.some(x=>x.a.level==='bad')?'bad':st.alerts.length?'warn':'ok','brain-circuit',can('predictive')?'maint/ai':'maint/status')}
 ${tile('Open safety items',st.pending+st.openInc+st.failed.length,`Permits ${st.pending} · incidents ${st.openInc} · failed checks ${st.failed.length}`,st.failed.length?'bad':st.pending+st.openInc?'warn':'ok','hard-hat','ehs/permits')}
 ${tile('On site today',`${st.present+st.late} <small>/ ${st.staffN}</small>`,`${st.late} late, ${st.absent} absent`,st.absent>1?'warn':'ok','users',can('staff')?'staff/att':'')}</div>
 <div class="grid g-2"><div class="panel"><h2>${ic('target')}Today against target</h2><div class="row" style="gap:16px">${ring(tp,tp>=100?'ok':tp>=55?'warn':'bad',fN(tp)+'%',88)}<div><b class="mono" style="font-size:22px">${fN(st.tToday,1)} t</b><div class="mute">of ${fN(st.targetDay)} t planned today, all materials</div></div></div>${MATS.map(m=>meter(m,st.byMat[m],st.tg[m])).join('')}</div>
 <div class="panel"><h2>${ic('siren')}Needs attention<span class="r">${at.length} item${at.length===1?'':'s'}</span></h2><div class="list">${at.length?at.map(a=>`<div class="li ${a.c}">${ic(a.i)}<div class="tx" style="color:var(--fg)"><b>${esc(a.t)}</b><small>${esc(a.s)}</small></div>${btn('nav','Open','','sm',`data-tab="${a.tab}" data-sub="${a.sub}"`)}</div>`).join(''):'<p class="mute">Nothing needs attention right now.</p>'}</div></div></div>
 <div class="panel"><h2>${ic('fuel')}Diesel burn, last 14 days<span class="r">litres per day, all machines</span></h2>${barChart(ds.daily,{line:ds.ma,unit:'L',barLabel:'Litres used',lineLabel:'7-day running average',partial:true})}</div>`};

V.diesel=st=>{const sub=curSub('diesel'),ds=st.ds,cost=can('costs'),ms=here(S.machines).filter(m=>m.diesel);let b='';
 if(sub==='overview'){const pct=ds.stock/ds.tank*100;
  b=`<div class="grid g-k">${tile('Tank level',`${fN(ds.stock)} <small>L</small>`,hbar(pct,pct<20?'bad':pct<40?'warn':'ok')+`${fN(pct)}% of ${fN(ds.tank)} L. ${fN(ds.cover,1)} days of cover.`,pct<20?'bad':pct<40?'warn':'ok','droplet')}
  ${tile('Used today',`${fN(ds.today)} <small>L</small>`,`7-day average ${fN(ds.avg7)} L/day`,'','gauge')}
  ${cost?tile('Average price',`${fN(ds.ppl*100,1)} <small>p/L</small>`,'Weighted across all deliveries','','pound-sterling')+tile('Running cost, 14 days',gbp(ds.l14*ds.ppl),`£${fN(ds.l14*ds.ppl/Math.max(1,ds.h14),2)} per operating hour`,'','receipt'):tile('Fuel per hour',`${fN(ds.l14/Math.max(1,ds.h14),1)} <small>L/h</small>`,'Fleet average, 14 days','','timer')}</div>
  <div class="panel"><h2>${ic('trending-up')}Consumption trend<span class="r">generator and heavy plant</span></h2>${barChart(ds.daily,{line:ds.ma,unit:'L',barLabel:'Litres used per day',lineLabel:'7-day running average',partial:true})}</div>
  <div class="panel"><h2>${ic('truck')}By machine, last 14 days</h2>${table(['Machine','Type','#Litres','#Hours run','#L/h',...(cost?['#Running cost','#£/h']:[]),'Against own baseline'],ms.map(m=>{const u=S.usage.filter(x=>x.machineId===m.id&&x.date>=DAYS[0]),l=sum(u,x=>x.litres),h=sum(u,x=>x.hours),a=analysis(m);
   return`<tr><td class="nw">${tag(m)} ${esc(m.name)}</td><td>${m.type}</td><td class="num">${fN(l)}</td><td class="num">${fN(h,1)}</td><td class="num">${fN(l/Math.max(.1,h),1)}</td>${cost?`<td class="num">${gbp(l*ds.ppl)}</td><td class="num">£${fN(l*ds.ppl/Math.max(.1,h),2)}</td>`:''}<td>${a.fuel>12?`<span class="pill bad">+${fN(a.fuel)}% anomaly</span>`:a.fuel>6?`<span class="pill warn">+${fN(a.fuel)}%</span>`:`<span class="pill ok">Normal</span>`}</td></tr>`}))}</div>`}
 if(sub==='deliveries')b=table(['Date','Supplier','#Litres',...(cost?['#Cost','#p/L']:[]),'Received by'],here(S.deliveries).sort((a,b)=>a.date<b.date?1:-1).map(d=>`<tr><td class="nw">${fD(d.date)}${pq(d)}</td><td>${esc(d.supplier)}</td><td class="num">${fN(d.litres)}</td>${cost?`<td class="num">${gbp(d.cost)}</td><td class="num">${fN(d.cost/d.litres*100,1)}</td>`:''}<td>${esc(d.receivedBy)}</td></tr>`),'No deliveries recorded.');
 if(sub==='usage')b=table(['Date','Machine','#Litres','#Hours','#L/h',...(cost?['#Cost']:[])],here(S.usage).sort((a,b)=>a.date<b.date?1:-1).slice(0,60).map(u=>{const m=mach(u.machineId);return`<tr><td class="nw">${fD(u.date)}${pq(u)}</td><td class="nw">${tag(m)} ${esc(m.name)}</td><td class="num">${fN(u.litres)}</td><td class="num">${fN(u.hours,1)}</td><td class="num">${fN(u.litres/Math.max(.1,u.hours),1)}</td>${cost?`<td class="num">${gbp(u.litres*ds.ppl)}</td>`:''}</tr>`}))+'<p class="note">Showing the latest 60 entries.</p>';
 return head('Diesel management','Deliveries into the tank, daily draw-off per machine, and what it costs to run each one.',(can('deliveries')?btn('addDelivery','Record delivery','truck'):'')+btn('addUsage','Log daily usage','plus','pri'))+tabs('diesel')+b};

V.maint=st=>{const sub=curSub('maint'),ms=here(S.machines);let b='';
 if(sub==='schedule'){const rows=here(S.maint).sort((a,b)=>(a.status==='Done')-(b.status==='Done')||(a.due<b.due?-1:1));
  b=table(['Due','Machine','Type','Status','Notes','Assigned to',''],rows.map(x=>{const m=mach(x.machineId),od=x.status!=='Done'&&x.due<T;
   return`<tr><td class="nw">${fD(x.due)}${pq(x)}</td><td class="nw">${tag(m)}</td><td>${x.type}</td><td>${od?pill('Overdue'):pill(x.status)}</td><td>${esc(x.notes)}</td><td class="nw">${esc(x.by)}</td><td class="nw">${x.status==='Done'?`<span class="mute">${fD(x.doneOn)}</span>`:can('schedule')?btn('maintNext',x.status==='Scheduled'?'Start':'Complete',x.status==='Scheduled'?'play':'check','sm',`data-id="${x.id}"`):''}</td></tr>`}))}
 if(sub==='status')b=`<div class="grid g-c">${ms.map(m=>{const s=mStatus(m),sv=(m.hours-m.lastServiceAt)/m.serviceEvery*100,gr=(m.hours-m.lastGreaseAt)/m.greaseEvery*100;
  return`<div class="card s-${PILL[s]}"><div class="hd">${tag(m)}<b>${esc(m.name)}</b></div><div>${pill(s)}</div><div><div class="mh"><span class="mute">Service interval</span><span class="mono">${fN(m.hours-m.lastServiceAt)} / ${m.serviceEvery} h</span></div>${hbar(sv,sv>100?'bad':sv>80?'warn':'ok')}</div><div><div class="mh"><span class="mute">Since greased</span><span class="mono">${fN(m.hours-m.lastGreaseAt)} / ${m.greaseEvery} h</span></div>${hbar(gr,gr>100?'warn':'ok')}</div><div class="row">${btn('greased','Mark greased','droplet','sm',`data-id="${m.id}"`)}${btn('openMachine','Logs','clipboard-list','sm',`data-id="${m.id}"`)}</div></div>`}).join('')}</div>`;
 if(sub==='ai'){const an=ms.map(m=>({m,a:analysis(m),s:mStatus(m)})).sort((a,b)=>b.a.risk-a.a.risk),al=an.filter(x=>x.a.risk>=40);
  b=`<p class="note">${ic('info')}Simulated model. Risk is scored on this device from operating hours since service, greasing intervals, each machine's fuel burn per hour against its own baseline, and recent breakdowns. It is a demonstration, not a trained ML model.</p>
  <div class="grid g-2">${al.length?al.map(({m,a})=>`<div class="card s-${a.level}"><div class="hd">${ic('triangle-alert',a.level)}${tag(m)}<b>${esc(m.name)}</b><span class="pill ${a.level}" style="margin-left:auto">${a.risk}% failure risk</span></div><div>Likely component: <b>${a.comp}</b>. Estimated margin about <b class="mono">${a.eta} h</b> of operation.</div><div class="list">${a.sig.map(s=>`<div class="li">${ic('activity','mute')}<div class="tx">${s}</div></div>`).join('')}</div><div class="row">${can('schedule')?btn('workOrder','Raise work order','wrench','sm pri',`data-id="${m.id}"`):''}${btn('openMachine','Machine logs','clipboard-list','sm',`data-id="${m.id}"`)}</div></div>`).join(''):'<div class="panel"><p class="mute">No machine is above the 40% alert line.</p></div>'}</div>
  <div class="panel"><h2>${ic('cpu')}All machines</h2>${table(['Machine','Status','#Health','#Risk','#Fuel vs baseline','#Service used','Signal'],an.map(({m,a,s})=>`<tr><td class="nw">${tag(m)} ${esc(m.name)}</td><td>${pill(s)}</td><td class="num">${a.health}</td><td class="num ${a.level}">${a.risk}%</td><td class="num">${m.diesel?(a.fuel>=0?'+':'')+fN(a.fuel)+'%':'n/a'}</td><td class="num">${fN(a.svc*100)}%</td><td>${a.sig[0]||'<span class="mute">No signals</span>'}</td></tr>`))}</div>`}
 return head('Maintenance & predictive AI','Greasing, inspections, services and breakdowns, with early warnings before a component fails.',(can('schedule')?btn('addMaint','Schedule task','calendar-plus'):'')+btn('addBreakdown','Report breakdown','triangle-alert','pri'))+tabs('maint')+b};

let wb={stage:0,reading:0};
V.prod=st=>{const sub=curSub('prod');let b='';
 if(sub==='output'){const hist=DAYS.map(d=>({label:fD(d),short:fD(d).slice(0,2),v:sum(here(S.production).filter(p=>p.date===d),p=>p.tonnes)}));
  b=`<div class="grid g-2"><div class="panel"><h2>${ic('target')}Today, target vs actual</h2>${meter('All materials',st.tToday,st.targetDay)}<hr style="border:0;border-top:1px solid var(--line);width:100%;margin:0">${MATS.map(m=>meter(m,st.byMat[m],st.tg[m])).join('')}<p class="note">The white marker is the daily target.</p></div>
  <div class="panel"><h2>${ic('chart-column')}Daily tonnage, last 14 days</h2>${barChart(hist,{line:hist.map(()=>st.targetDay),unit:'t',dp:1,barLabel:'Tonnes processed',lineLabel:`Daily target ${fN(st.targetDay)} t`,partial:true})}<div class="kv"><div><span>Last 7 days</span><b>${fN(st.t7,1)} t</b></div><div><span>Against target</span><b class="${st.attain>=100?'ok':st.attain>=85?'warn':'bad'}">${fN(st.attain)}%</b></div><div><span>Diesel per tonne</span><b>${fN(st.lPerT,2)} L</b></div></div></div></div>`}
 if(sub==='wb'){const tk=here(S.tickets).filter(t=>t.date===T),inb=sum(tk.filter(t=>t.dir==='Inbound'),t=>t.net),out=sum(tk.filter(t=>t.dir==='Outbound'),t=>t.net);
  const stg=wb.stage,stat=['Bridge empty','Truck on bridge · stable','Truck in yard · bridge clear','Truck back on bridge · stable'][stg];
  b=`<div class="grid g-2"><div class="panel"><h2>${ic('scale')}Truck scale<span class="r">simulated indicator feed</span></h2><div class="scale"><div class="rd"><span id="wb-read">${fN(wb.reading)}</span><small> kg</small></div><div class="st">${stat}</div></div>
  ${stg===0?`<p class="mute" style="margin:0">Weights are read straight from the scale indicator, so nobody types them in. This demo simulates the truck and the indicator.</p>${btn('wbArrive','Simulate truck arrival','truck','pri')}`:
  `<div class="fg"><label class="fl" for="wb-reg"><span>Registration</span><input id="wb-reg" value="${esc(wb.reg)}"${stg>1?' disabled':''}></label><label class="fl" for="wb-haul"><span>Haulier</span><input id="wb-haul" value="${esc(wb.haulier)}"${stg>1?' disabled':''}></label><label class="fl" for="wb-dir"><span>Direction</span><select id="wb-dir" disabled><option>${wb.dir}</option></select></label><label class="fl" for="wb-mat"><span>Material</span><input id="wb-mat" value="${esc(wb.material)}"${stg>1?' disabled':''}></label></div>
  ${wb.w1?`<div class="kv"><div><span>First weigh (${wb.dir==='Inbound'?'gross':'tare'})</span><b>${fN(wb.w1)} kg</b></div></div>`:''}
  <div class="row">${stg===1?btn('wbCap1','Capture first weigh','download','pri'):stg===2?`<span class="mute">${ic('loader','spin')} ${wb.dir==='Inbound'?'Tipping':'Loading'} in the yard…</span>`:btn('wbCap2','Capture second weigh and issue ticket','ticket','pri')}${btn('wbCancel','Cancel','x')}</div>`}</div>
  <div class="panel"><h2>${ic('arrow-left-right')}Today over the bridge</h2><div class="kv"><div><span>Inbound scrap</span><b>${fN(inb/1000,2)} t</b></div><div><span>Outbound commodity</span><b>${fN(out/1000,2)} t</b></div><div><span>Tickets</span><b>${tk.length}</b></div></div><p class="note">Inbound trucks weigh full then empty. Outbound trucks weigh empty then full. Net weight is the difference.</p></div></div>
  ${table(['Ticket','Time','Registration','Haulier','Direction','Material','#Gross kg','#Tare kg','#Net kg'],tk.map(t=>`<tr><td class="mono nw">${t.ticket}${pq(t)}</td><td class="mono">${t.time}</td><td class="mono nw">${esc(t.reg)}</td><td>${esc(t.haulier)}</td><td>${pill(t.dir)}</td><td>${esc(t.material)}</td><td class="num">${fN(t.gross)}</td><td class="num">${fN(t.tare)}</td><td class="num"><b>${fN(t.net)}</b></td></tr>`),'No tickets today.')}`}
 if(sub==='history')b=table(['Date','Shift','Team','Material','#Tonnes',...(can('del')?['']:[])],here(S.production).sort((a,b)=>a.date<b.date?1:-1).slice(0,80).map(p=>`<tr><td class="nw">${fD(p.date)}${pq(p)}</td><td>${p.shift}</td><td>Team ${p.team}</td><td>${p.material}</td><td class="num">${fN(p.tonnes,1)}</td>${can('del')?`<td>${btn('delRec','','trash-2','sm',`data-col="production" data-id="${p.id}" aria-label="Delete entry"`)}</td>`:''}</tr>`))+'<p class="note">Showing the latest 80 entries.</p>';
 return head('Production & weighbridge','Tonnes processed by material, measured against the daily target, with truck weights captured from the scale.',btn('addProd','Log production','plus','pri'))+tabs('prod')+b};

const SHIFT_I={Morning:'sun',Afternoon:'sunset',Night:'moon'};
const SAMPLE=['Log 14 tonnes processed by Team A','Diesel 120 litres EX-01 6 hours','Breakdown on SH-01 hydraulic leak at the ram','Greased WL-01','Mark Priya late','Near miss at the tipping bay, loose load on a skip wagon'];
V.staff=st=>{const sub=curSub('staff'),ps=here(S.staff),att=S.attendance[T]||{};let b='',acts='';
 if(sub==='att'){acts=btn('addStaff','Add team member','user-plus');
  b=`<div class="grid g-k">${tile('Present',st.present,'','ok','user-check')}${tile('Late',st.late,'','warn','clock')}${tile('Absent',st.absent,'','bad','user-x')}${tile('Not marked',st.staffN-st.present-st.late-st.absent,'','','circle-help')}</div>`+
  ['Morning','Afternoon','Night'].map(sh=>{const l=ps.filter(p=>p.shift===sh);return`<div class="panel"><h2>${ic(SHIFT_I[sh])}${sh} shift<span class="r">${l.length} people</span></h2>${table(['Name','Role','Team','Shift','Attendance today'],l.map(p=>`<tr><td class="nw"><b>${esc(p.name)}</b></td><td>${esc(p.role)}</td><td>Team ${p.team}</td><td><select id="sh-${p.id}" data-c="shift" data-id="${p.id}" aria-label="Shift for ${esc(p.name)}" style="width:auto">${['Morning','Afternoon','Night'].map(x=>`<option${x===p.shift?' selected':''}>${x}</option>`).join('')}</select></td><td><div class="seg">${[['P','Present','ok'],['L','Late','warn'],['A','Absent','bad']].map(([v,l,c])=>`<button class="${c}${att[p.id]===v?' on':''}" data-a="att" data-id="${p.id}" data-v="${v}" aria-pressed="${att[p.id]===v}">${l}</button>`).join('')}</div></td></tr>`),'Nobody on this shift.')}</div>`}).join('')}
 if(sub==='tasks'){acts=btn('addTask','Assign task','plus','pri');const ts=here(S.tasks).filter(t=>t.date===T);
  b=`<div class="panel"><h2>${ic('list-checks')}Today's assignments<span class="r">${ts.filter(t=>t.done).length} of ${ts.length} done</span></h2><div class="list">${ts.length?ts.map(t=>{const p=S.staff.find(x=>x.id===t.staffId)||{name:'Unassigned',team:'-'};return`<label class="li" for="tk-${t.id}"><input type="checkbox" id="tk-${t.id}" data-c="task" data-id="${t.id}"${t.done?' checked':''} style="margin-top:4px"><div class="tx" style="${t.done?'text-decoration:line-through;color:var(--mute)':''}">${esc(t.text)}${pq(t)}<small>${esc(p.name)} · Team ${p.team}</small></div></label>`}).join(''):'<p class="mute">No tasks assigned today.</p>'}</div></div>`}
 if(sub==='score'){const w=dAgo(7),teams=['A','B','C'].map(t=>{const mem=ps.filter(p=>p.team===t),tn=sum(here(S.production).filter(p=>p.team===t&&p.date>=w),p=>p.tonnes);let a=0,n=0;for(let i=0;i<7;i++){const d=S.attendance[dAgo(i)]||{};mem.forEach(p=>{if(d[p.id]){n++;if(d[p.id]!=='A')a+=d[p.id]==='P'?1:.5}})}
   const tk=here(S.tasks).filter(x=>mem.some(p=>p.id===x.staffId));return{t,mem,tn,att:n?a/n*100:0,tasks:tk.length?tk.filter(x=>x.done).length/tk.length*100:null}}),mx=Math.max(1,...teams.map(x=>x.tn));
  b=`<div class="grid g-c">${teams.map(x=>{const out=x.tn/mx*100,sc=Math.round(.45*out+.35*x.att+.2*(x.tasks??x.att)),c=sc>=80?'ok':sc>=60?'warn':'bad';
   return`<div class="card s-${c}"><div class="hd"><b style="font:700 22px var(--f-d);text-transform:uppercase">Team ${x.t}</b><span style="margin-left:auto">${ring(sc,c,sc,56)}</span></div><div class="mute">${x.mem.length} people · ${[...new Set(x.mem.map(p=>p.shift))].join(', ')||'no shift'}</div>
   <div><div class="mh"><span>Output, 7 days</span><span class="mono">${fN(x.tn,1)} t</span></div>${hbar(out,'warn')}</div><div><div class="mh"><span>Attendance, 7 days</span><span class="mono">${fN(x.att)}%</span></div>${hbar(x.att,x.att>=90?'ok':'warn')}</div><div><div class="mh"><span>Tasks closed</span><span class="mono">${x.tasks==null?'none set':fN(x.tasks)+'%'}</span></div>${hbar(x.tasks||0,'info')}</div></div>`}).join('')}</div><p class="note">${ic('info')}Score weights output 45%, attendance 35% and task completion 20%. A late arrival counts as half a day.</p>`}
 if(sub==='chat')b=`<div class="grid g-2"><div class="panel"><h2>${ic('message-circle')}Supervisor log<span class="r">simulated assistant</span></h2><div class="chat" id="chat">${S.chat.map(m=>`<div class="msg ${m.who}">${esc(m.text)}<small>${hhmm(m.t)}</small></div>`).join('')}</div>
  <form class="cin" id="chatform"><button type="button" class="btn mic" id="btn-mic" data-a="mic" aria-label="Dictate">${ic('mic')}</button><input id="chat-in" placeholder="Type or dictate an update" autocomplete="off" aria-label="Update"><button class="btn pri" aria-label="Send">${ic('send')}</button></form>
  <p class="note">${ic('info')}The microphone button simulates dictation by typing a sample update. Messages are parsed on this device; nothing is sent to WhatsApp.</p></div>
  <div class="panel"><h2>${ic('wand-sparkles')}Things it understands</h2><div class="row">${SAMPLE.map(s=>`<button class="chip" data-a="chip">${esc(s)}</button>`).join('')}</div><div class="list"><div class="li">${ic('factory','warn')}<div class="tx">Tonnes with an optional material and team<small>Files a production entry</small></div></div><div class="li">${ic('fuel','warn')}<div class="tx">Litres with a machine code<small>Files diesel usage</small></div></div><div class="li">${ic('wrench','warn')}<div class="tx">"Breakdown" or "Greased" with a machine code<small>Updates the maintenance schedule</small></div></div><div class="li">${ic('users','warn')}<div class="tx">"Mark" a first name present, late or absent<small>Updates attendance</small></div></div><div class="li">${ic('triangle-alert','warn')}<div class="tx">"Near miss" or "incident" with a description<small>Opens a safety report</small></div></div></div></div></div>`;
 return head('Staff & voice log','Who is on site, which shift they are on, what they have been asked to do, and a quick way to log from the yard.',acts)+tabs('staff')+b};

V.ehs=st=>{const sub=curSub('ehs');let b='',acts='';
 if(sub==='fork'){acts=btn('newCheck','Start forklift check','clipboard-check','pri');
  b=table(['Date','Truck','Check','Operator','Result','Failed items'],here(S.checks).map(c=>`<tr><td class="nw">${fD(c.date)}${pq(c)}</td><td>${tag(mach(c.machineId))}</td><td>${c.when}</td><td>${esc(c.operator)}</td><td>${pill(c.result)}</td><td>${c.fails.length?esc(c.fails.join(', ')):'<span class="mute">None</span>'}</td></tr>`),'No checks recorded.')+'<p class="note">A failed item takes the truck out of service and raises an inspection in the maintenance schedule.</p>'}
 if(sub==='permits'){acts=btn('addPermit','Request permit','file-plus','pri');
  b=`<div class="grid g-c">${here(S.permits).map(p=>`<div class="card s-${PILL[p.status]==='mute'?'':PILL[p.status]}"><div class="hd">${ic(p.type==='Hot Work'?'flame':p.type==='Confined Space'?'box':'construction')}<b>${p.type}</b><span style="margin-left:auto">${pill(p.status)}</span></div><div>${esc(p.work)}</div><div class="kv"><div><span>Location</span><b style="font-family:var(--f-b)">${esc(p.location)}</b></div><div><span>Requested by</span><b style="font-family:var(--f-b)">${esc(p.requester)}</b></div><div><span>Date</span><b>${fD(p.date)}</b></div>${p.approver?`<div><span>Signed by</span><b style="font-family:var(--f-b)">${esc(p.approver)}</b></div>`:''}</div>
  <div class="row">${p.status==='Pending'?(can('approve')?btn('permit','Approve','check','sm pri',`data-id="${p.id}" data-v="Approved"`)+btn('permit','Reject','x','sm dng',`data-id="${p.id}" data-v="Rejected"`):`<span class="note">${ic('lock')}Needs a Plant Manager or Owner to approve.</span>`):p.status==='Approved'?btn('permit','Close out','lock','sm',`data-id="${p.id}" data-v="Closed"`):''}${pq(p)}</div></div>`).join('')||'<div class="panel"><p class="mute">No permits requested at this site.</p></div>'}</div>`}
 if(sub==='env'){acts=btn('addEnv','Add compliance log','leaf','pri');
  b=table(['Date','Check','Reading','Status','Notes','Logged by'],here(S.envlogs).sort((a,b)=>a.date<b.date?1:-1).map(e=>`<tr><td class="nw">${fD(e.date)}${pq(e)}</td><td>${esc(e.category)}</td><td class="mono">${esc(e.reading)}</td><td>${pill(e.status)}</td><td>${esc(e.notes)}</td><td class="nw">${esc(e.by)}</td></tr>`),'No environmental logs yet.')+'<p class="note">Keep these as the evidence trail for permit audits.</p>'}
 if(sub==='inc'){acts=btn('addIncident','Report incident or near miss','triangle-alert','pri');
  b=`<div class="grid g-k">${tile('Days since last injury',st.sinceInc==null?'–':st.sinceInc,'First aid or worse',st.sinceInc!=null&&st.sinceInc<7?'warn':'ok','shield-check')}${tile('Near misses, 7 days',st.nearMiss7,'Reporting these prevents injuries','','eye')}${tile('Open actions',st.openInc,'',st.openInc?'warn':'ok','circle-alert')}</div>`+
  table(['Date','Type','Severity','Location','What happened','Action taken','Status',''],here(S.incidents).sort((a,b)=>a.date<b.date?1:-1).map(i=>`<tr><td class="nw">${fD(i.date)}${pq(i)}</td><td class="nw">${i.type}</td><td><span class="pill ${i.severity==='High'?'bad':i.severity==='Medium'?'warn':'mute'}">${i.severity}</span></td><td>${esc(i.location)}</td><td>${esc(i.desc)}</td><td>${esc(i.action)}</td><td>${pill(i.status)}</td><td>${i.status==='Open'?btn('incClose','Close','check','sm',`data-id="${i.id}"`):''}</td></tr>`),'Nothing reported.')}
 return head('Health, safety & environment','Forklift checks, permits to work, environmental evidence and incident reports in one place.',acts)+tabs('ehs')+b};

V.fleet=st=>{const sub=curSub('fleet'),ms=here(S.machines);let b='';
 const live=ms.map(m=>liveOf(m));
 if(sub==='grid')b=`<div class="grid g-k">${tile('Running',live.filter(x=>x==='Running').length,'','ok','play')}${tile('Idle',live.filter(x=>x==='Idle').length,'','','pause')}${tile('Down',live.filter(x=>x==='Down').length,'',live.includes('Down')?'bad':'ok','octagon-x')}${tile('Fleet hours',`<span data-tot>${fN(sum(ms,m=>m.hours))}</span>`,'Total operating hours','','timer')}</div>
  <div class="grid g-c">${ms.map(m=>{const l=liveOf(m),a=analysis(m);return`<button class="card s-${PILL[l]==='mute'?'':PILL[l]}" data-a="openMachine" data-id="${m.id}" style="cursor:pointer;text-align:left"><div class="hd">${tag(m)}<b>${esc(m.name)}</b><span style="margin-left:auto">${pill(l)}</span></div><div class="mute">${m.type} · ${ZONES[m.zone]}</div><div class="row" style="gap:14px;flex-wrap:nowrap">${ring(a.health,a.level,a.health,58)}<div class="kv" style="flex:1"><div><span>Hours</span><b data-hrs="${m.id}">${fN(m.hours,1)}</b></div><div><span>Upkeep</span><b style="font-family:var(--f-b);font-size:12px">${mStatus(m)}</b></div></div></div></button>`}).join('')}</div><p class="note">${ic('radio')}Telemetry is simulated: hour counters tick while a machine is running.</p>`;
 if(sub==='zones')b=`<div class="grid g-c">${Object.entries(ZONES).map(([z,n])=>{const l=ms.filter(m=>m.zone===z);return`<div class="zone"><h3>${n}</h3><div class="row">${l.map(m=>`<button class="mc ${PILL[liveOf(m)]}" data-a="openMachine" data-id="${m.id}" title="${esc(m.name)} · ${liveOf(m)}"><i></i><span style="color:var(--fg)" class="mono">${m.code}</span></button>`).join('')||'<span class="mute">Empty</span>'}</div></div>`}).join('')}</div><p class="note">${ic('map-pin')}Open a machine to move it to another zone.</p>`;
 if(sub==='qr')b=`<div class="grid g-2"><div class="panel"><h2>${ic('scan-line')}Scanner<span class="r">simulated camera</span></h2><div class="cam"><div class="sl"></div><div class="fr" id="cam-fr">Tap a machine tag on the right to hold it up to the camera</div></div>${btn('scanRandom','Scan the nearest machine','qr-code','pri')}<p class="note">${ic('info')}On a real handset this opens the camera. Here, tapping a tag stands in for scanning it.</p></div>
  <div class="panel"><h2>${ic('qr-code')}Machine tags</h2><div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(112px,1fr))">${ms.map(m=>`<button class="qrb" data-a="scan" data-id="${m.id}">${qr(m.id)}${tag(m)}</button>`).join('')}</div></div></div>`;
 return head('Equipment & IoT fleet','Live status, operating hours, yard location and health for every machine. Scan a tag to open its logs.',btn('sub','Scan QR code','qr-code','pri','data-tab="fleet" data-sub="qr"'))+tabs('fleet')+b};

let repBusy=false;
V.reports=st=>{const sub=curSub('reports');let b='';
 if(sub==='exec'){const r=S.reports[0];
  b=`<div class="panel"><div class="row">${can('multisite')?`<label class="fl" for="rep-scope" style="flex-direction:row;align-items:center;gap:8px"><span>Scope</span><select id="rep-scope" style="width:auto"><option value="${S.ui.site}">${st.name}</option><option value="ALL">All sites</option></select></label>`:''}<button class="btn pri" data-a="genReport"${repBusy?' disabled':''}>${ic(repBusy?'loader':'sparkles',repBusy?'spin':'')}${repBusy?'Analysing today\'s records…':'Generate daily executive report'}</button>${r&&!repBusy?btn('copyReport','Copy as text','copy'):''}</div><p class="note">${ic('info')}Simulated AI. The summary is assembled on this device from today's logged records, so every figure traces back to an entry.</p></div>
  ${r&&!repBusy?`<div class="panel"><h2>${ic('file-text')}${esc(r.title)}<span class="r">Generated ${hhmm(r.t)} · ${fD(r.date)}</span></h2><p style="margin:0;font-size:17px;max-width:70ch">${esc(r.headline)}</p><div class="rep-out">${r.sections.map(s=>`<section><h3>${ic(s.i)}${s.h}</h3><ul>${s.lines.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></section>`).join('')}</div></div>`:repBusy?'':'<div class="panel"><p class="mute">No report generated yet. It takes a couple of seconds and covers diesel burn, tonnage, safety and maintenance bottlenecks.</p></div>'}
  ${S.reports.length>1?`<div class="panel"><h2>${ic('history')}Earlier reports</h2><div class="list">${S.reports.slice(1,8).map(x=>`<div class="li">${ic('file-text','mute')}<div class="tx">${esc(x.title)}<small>${fD(x.date)} at ${hhmm(x.t)}. ${esc(x.headline)}</small></div></div>`).join('')}</div></div>`:''}`}
 if(sub==='sites'){const all=S.sites.map(s=>siteStats(s.id)),rows=[['Output, last 7 days','t7',1,' t',1],['Target attainment','attain',0,'%',1],['Diesel per tonne','lPerT',2,' L',-1],['Fuel cost per tonne','costPerT',2,'',-1,'£'],['Fleet availability','avail',0,'%',1],['Predictive alerts','alertsN',0,'',-1],['Open safety items','safety',0,'',-1],['Attendance today','attPct',0,'%',1]];
  all.forEach(a=>{a.alertsN=a.alerts.length;a.safety=a.pending+a.openInc+a.failed.length});
  b=`<div class="grid g-c">${all.map(a=>`<div class="card s-${a.attain>=100?'ok':a.attain>=85?'warn':'bad'}"><div class="hd">${ic('building-2')}<b>${a.name}</b><span class="pill ${a.attain>=100?'ok':a.attain>=85?'warn':'bad'}" style="margin-left:auto">${fN(a.attain)}% of target</span></div>${meter('Today',a.tToday,a.targetDay)}<div class="kv"><div><span>7-day output</span><b>${fN(a.t7)} t</b></div><div><span>Diesel/tonne</span><b>${fN(a.lPerT,2)} L</b></div><div><span>In repair</span><b>${a.inRepair.length}</b></div></div></div>`).join('')}</div>
  <div class="panel"><h2>${ic('git-compare-arrows')}Side by side<span class="r">best figure in green</span></h2>${table(['Measure',...all.map(a=>'#'+a.name)],rows.map(([l,k,d,u,dir,pre])=>{const vals=all.map(a=>a[k]),best=dir>0?Math.max(...vals):Math.min(...vals);return`<tr><td>${l}</td>${all.map(a=>`<td class="num${a[k]===best?' best':''}">${pre||''}${fN(a[k],d)}${u}</td>`).join('')}</tr>`}))}</div>
  <div class="panel"><h2>${ic('chart-column')}Output last 7 days against target</h2>${all.map(a=>meter(a.name,a.t7,a.target7)).join('')}</div>`}
 if(sub==='rbac')b=`<div class="panel"><h2>${ic('shield')}Who can see and do what<span class="r">Current role: ${S.ui.role}</span></h2>${table(['Permission',...ROLES],[...Object.values(BASE).map(l=>`<tr><td>${l}</td>${ROLES.map(()=>`<td class="ok">${ic('check')}</td>`).join('')}</tr>`),...Object.values(PERM).map(p=>`<tr><td>${p.l}</td>${ROLES.map((_,i)=>`<td class="${p.r.includes(i)?'ok':'mute'}">${ic(p.r.includes(i)?'check':'minus')}</td>`).join('')}</tr>`)])}<p class="note">${ic('info')}Switch role in the top bar to see modules, costs and approval buttons appear or disappear.</p></div>`;
 return head('Executive reports','A daily summary for the people who make the calls, and a comparison across yards.')+tabs('reports')+b};

function buildReport(scope){
 const ids=scope==='ALL'?S.sites.map(s=>s.id):[scope],st=ids.map(siteStats),A=f=>sum(st,f),multi=st.length>1;
 const tT=A(x=>x.tToday),tg=A(x=>x.targetDay),lit=A(x=>x.ds.today),avg=A(x=>x.ds.avg7),cost=A(x=>x.ds.today*x.ds.ppl),rep=st.flatMap(x=>x.inRepair),od=st.flatMap(x=>x.overdue),al=st.flatMap(x=>x.alerts),pend=A(x=>x.pending),oi=A(x=>x.openInc),failed=st.flatMap(x=>x.failed);
 const nm=x=>(multi?siteName(x.m.site).split(' ')[0]+' ':'')+x.m.code,pct=tT/tg*100;
 const sec=[];
 sec.push({h:'Production',i:'factory',lines:[`${fN(tT,1)} t processed so far against a ${fN(tg)} t daily target (${fN(pct)}%).`,...(multi?st.map(x=>`${x.name}: ${fN(x.tToday,1)} t of ${fN(x.targetDay)} t. Seven-day attainment ${fN(x.attain)}%.`):MATS.map(m=>`${m}: ${fN(st[0].byMat[m],1)} t of ${fN(st[0].tg[m])} t.`))]});
 sec.push({h:'Diesel',i:'fuel',lines:[`${fN(lit)} L burned today, costing about ${gbp(cost)}. The 7-day average is ${fN(avg)} L/day.`,...st.map(x=>`${multi?x.name+': ':''}${fN(x.ds.stock)} L in the tank, ${fN(x.ds.cover,1)} days of cover. ${fN(x.lPerT,2)} L per tonne over the last week.`)]});
 sec.push({h:'Maintenance bottlenecks',i:'wrench',lines:[rep.length?`In repair: ${rep.map(nm).join(', ')}.`:'No machines in repair.',od.length?`Overdue maintenance: ${od.map(nm).join(', ')}.`:'No overdue maintenance.',...al.slice(0,3).map(x=>`${nm(x)} failure risk ${x.a.risk}%: ${x.a.sig[0]||'wear'}. Likely ${x.a.comp}.`)]});
 sec.push({h:'Safety',i:'hard-hat',lines:[`${oi} open incident or near-miss action${oi===1?'':'s'}, ${A(x=>x.nearMiss7)} near miss${A(x=>x.nearMiss7)===1?'':'es'} reported in 7 days.`,`${pend} permit${pend===1?'':'s'} to work waiting for approval.`,failed.length?`Forklift checks failed: ${failed.map(c=>mach(c.machineId).code+' ('+c.fails.join(', ')+')').join('; ')}.`:'All recent forklift checks passed.']});
 sec.push({h:'Staffing',i:'users',lines:[`${A(x=>x.present+x.late)} of ${A(x=>x.staffN)} on site. ${A(x=>x.late)} late, ${A(x=>x.absent)} absent.`]});
 const act=[];
 al.filter(x=>x.a.level==='bad').forEach(x=>act.push(`Plan a stoppage on ${nm(x)} within about ${x.a.eta} operating hours and inspect the ${x.a.comp}.`));
 rep.forEach(x=>act.push(`Chase the repair on ${nm(x)}; it is holding back throughput.`));
 od.forEach(x=>act.push(`Clear the overdue maintenance on ${nm(x)}.`));
 st.filter(x=>x.ds.cover<6).forEach(x=>act.push(`Order diesel for ${x.name}: ${fN(x.ds.cover,1)} days of cover left.`));
 if(pend)act.push(`Decide the ${pend} pending permit${pend>1?'s':''} so the work can start.`);
 failed.forEach(c=>act.push(`Keep ${mach(c.machineId).code} out of service until the failed check items are fixed.`));
 st.filter(x=>x.attain<85).forEach(x=>act.push(`${x.name} is at ${fN(x.attain)}% of target over 7 days. Review manning and machine downtime there.`));
 sec.push({h:'Recommended actions',i:'list-checks',lines:act.length?act:['No blockers today. Keep to the plan.']});
 const head=`${multi?'Across all sites, output':'Output'} is at ${fN(pct)}% of today's target with ${rep.length} machine${rep.length===1?'':'s'} in repair, ${al.length} predictive alert${al.length===1?'':'s'} and ${oi+pend+failed.length} open safety item${oi+pend+failed.length===1?'':'s'}.`;
 return{title:`Daily executive report · ${multi?'All sites':st[0].name}`,date:T,t:Date.now(),headline:head,sections:sec}}

/* ---------- machine modal ---------- */
function openMachine(id){const m=mach(id),a=analysis(m),s=mStatus(m),fu=S.usage.filter(x=>x.machineId===id).sort((x,y)=>x.date<y.date?1:-1).slice(0,10),ck=S.checks.filter(x=>x.machineId===id),logs=S.maint.filter(x=>x.machineId===id).sort((x,y)=>x.due<y.due?1:-1);
 modal(`<h2>${tag(m)}${esc(m.name)}<button class="btn sm x" data-a="closeModal" aria-label="Close">${ic('x')}</button></h2>
 <div class="row">${pill(liveOf(m))}${pill(s)}<span class="mute">${m.type} · ${siteName(m.site)}</span></div>
 <div class="row" style="align-items:flex-start;gap:16px"><div>${qr(m.id,104)}</div>${ring(a.health,a.level,a.health,104)}<div class="kv" style="flex:1;min-width:200px"><div><span>Operating hours</span><b>${fN(m.hours,1)}</b></div><div><span>Failure risk</span><b class="${a.level}">${a.risk}%</b></div><div><span>Next service in</span><b>${fN(m.serviceEvery-(m.hours-m.lastServiceAt))} h</b></div><div><span>Since greased</span><b>${fN(m.hours-m.lastGreaseAt)} h</b></div></div></div>
 <label class="fl" for="mz"><span>Yard zone</span><select id="mz" data-c="zone" data-id="${m.id}">${Object.entries(ZONES).map(([z,n])=>`<option value="${z}"${z===m.zone?' selected':''}>${n}</option>`).join('')}</select></label>
 <div class="row">${btn('addBreakdown','Log quick breakdown','triangle-alert','pri',`data-id="${m.id}"`)}${btn('greased','Mark greased','droplet','',`data-id="${m.id}" data-keep="1"`)}${m.diesel?btn('addUsage','Log fuel','fuel','',`data-id="${m.id}"`):''}</div>
 <details class="acc" open><summary>${ic('wrench')}Maintenance history<span>${logs.length}</span></summary><div class="list">${logs.length?logs.map(x=>`<div class="li">${ic(x.type==='Breakdown'?'triangle-alert':x.type==='Greasing'?'droplet':x.type==='Service'?'wrench':'search',x.type==='Breakdown'?'bad':'mute')}<div class="tx"><b>${x.type}</b> · ${fD(x.due)} · ${esc(x.by)}<small>${esc(x.notes)}</small></div>${x.status!=='Done'&&x.due<T?pill('Overdue'):pill(x.status)}</div>`).join(''):'<p class="mute">No maintenance recorded for this machine.</p>'}</div></details>
 ${m.diesel?`<details class="acc"><summary>${ic('fuel')}Fuel history<span>${fu.length}</span></summary>${table(['Date','#Litres','#Hours','#L/h'],fu.map(u=>`<tr><td>${fD(u.date)}</td><td class="num">${fN(u.litres)}</td><td class="num">${fN(u.hours,1)}</td><td class="num">${fN(u.litres/Math.max(.1,u.hours),1)}</td></tr>`),'No fuel logged.')}</details>`:''}
 ${m.type==='Forklift'?`<details class="acc"><summary>${ic('clipboard-check')}Inspection checks<span>${ck.length}</span></summary><div class="list">${ck.map(c=>`<div class="li"><div class="tx"><b>${c.when}</b> · ${fD(c.date)} · ${esc(c.operator)}<small>${c.fails.length?'Failed: '+esc(c.fails.join(', ')):'All items passed'}</small></div>${pill(c.result)}</div>`).join('')||'<p class="mute">No checks recorded.</p>'}</div></details>`:''}`)}

/* ---------- chat parser ---------- */
function parseCmd(txt){const t=txt.toLowerCase(),ms=here(S.machines);
 const m=ms.find(x=>{const c=x.code.toLowerCase();return t.includes(c)||t.includes(c.replace('-',' '))||t.includes(c.replace('-',''))});
 const num=re=>{const k=t.match(re);return k?parseFloat(k[1]):null};
 const litres=num(/(\d+(?:\.\d+)?)\s*(?:l|ltrs?|litres?|liters?)\b/),tonnes=num(/(\d+(?:\.\d+)?)\s*(?:t|tonnes?|tons?)\b/);
 if(litres!=null){if(!m)return'Which machine was that for? Add the machine code, for example "Diesel 120 litres EX-01".';if(!m.diesel)return`${m.code} is electric, so there is no diesel to log.`;
  const h=num(/(\d+(?:\.\d+)?)\s*(?:h|hrs?|hours?)\b/)||Math.round(litres/m.lph*10)/10;add('usage',{date:T,machineId:m.id,litres,hours:h});return`Logged ${fN(litres)} L for ${m.code} over ${fN(h,1)} h (${fN(litres/h,1)} L/h).`}
 if(tonnes!=null){const mat=/non[- ]?ferrous|alumini|copper|brass/.test(t)?'Non-Ferrous':/ferrous|steel|iron/.test(t)?'Ferrous':/plastic/.test(t)?'Plastics':/e-?waste|weee/.test(t)?'E-Waste':/paper|cardboard|occ/.test(t)?'Paper':null;
  const tm=(t.match(/team\s+([abc])\b/)||[])[1],sh=/night/.test(t)?'Night':/afternoon/.test(t)?'Afternoon':'Morning';
  add('production',{date:T,shift:sh,team:(tm||'a').toUpperCase(),material:mat||'Ferrous',tonnes});return`Logged ${fN(tonnes,1)} t of ${mat||'Ferrous'} for Team ${(tm||'a').toUpperCase()}, ${sh.toLowerCase()} shift.${mat?'':' No material given, so I filed it as Ferrous. A manager can delete it in Production history if that is wrong.'}`}
 if(m&&/greas/.test(t)){m.lastGreaseAt=m.hours;S.maint.filter(x=>x.machineId===m.id&&x.type==='Greasing'&&x.status!=='Done').forEach(x=>{x.status='Done';x.doneOn=T});add('maint',{machineId:m.id,type:'Greasing',due:T,status:'Done',doneOn:T,notes:'Logged by voice/WhatsApp.',by:S.ui.role});return`${m.code} marked as greased at ${fN(m.hours)} h.`}
 if(m&&/breakdown|broke|leak|fault|not working|stopped|seized|burst/.test(t)){add('maint',{machineId:m.id,type:'Breakdown',due:T,status:'In progress',notes:txt,by:S.ui.role});return`Breakdown raised on ${m.code}. It now shows as In Repair and the fitters can see it in the schedule.`}
 const av=/absent/.test(t)?'A':/late/.test(t)?'L':/present|on site|arrived/.test(t)?'P':null;
 if(av){const p=here(S.staff).find(x=>t.includes(x.name.split(' ')[0].toLowerCase()));if(p){(S.attendance[T]=S.attendance[T]||{})[p.id]=av;save();return`${p.name} marked ${{P:'present',L:'late',A:'absent'}[av]} for today.`}return'I could not match that name to anyone at this site.'}
 if(/near miss|incident|injur|accident/.test(t)){add('incidents',{date:T,type:/near miss/.test(t)?'Near miss':'Incident',severity:'Medium',location:'To be confirmed',desc:txt,action:'Awaiting review.',status:'Open',by:S.ui.role});return'Safety report opened. Add the location and actions in Health & safety when you are back at a desk.'}
 return'Saved as a note. I did not find tonnes, litres, a machine code or a name to file it against.'}

/* ---------- global search ---------- */
function doSearch(q){const box=$('#gres');q=q.trim().toLowerCase();if(q.length<2){box.hidden=true;box.innerHTML='';return}
 const r=[],hit=(...s)=>s.some(x=>String(x||'').toLowerCase().includes(q));
 here(S.machines).forEach(m=>{if(hit(m.code,m.name,m.type))r.push(['cpu',`${m.code} · ${m.name}`,'Machine',`data-m="${m.id}"`])});
 Object.entries(TABS).forEach(([id,t])=>{if(t.p&&!can(t.p))return;if(hit(t.l))r.push([t.i,t.l,'Module',`data-tab="${id}"`]);(SUBS[id]||[]).forEach(([sid,l,p])=>{if((!p||can(p))&&hit(l))r.push([t.i,l,t.l,`data-tab="${id}" data-sub="${sid}"`])})});
 if(can('staff'))here(S.staff).forEach(p=>{if(hit(p.name,p.role))r.push(['user',p.name,`${p.role} · ${p.shift}`,'data-tab="staff" data-sub="att"'])});
 here(S.permits).forEach(p=>{if(hit(p.type,p.work,p.requester))r.push(['file-check',`${p.type} permit`,p.status,'data-tab="ehs" data-sub="permits"'])});
 here(S.incidents).forEach(i=>{if(hit(i.type,i.desc))r.push(['triangle-alert',i.desc,i.type,'data-tab="ehs" data-sub="inc"'])});
 here(S.tickets).forEach(t=>{if(hit(t.reg,t.ticket,t.haulier))r.push(['scale',`${t.ticket} · ${t.reg}`,'Weighbridge ticket','data-tab="prod" data-sub="wb"'])});
 box.innerHTML=r.length?r.slice(0,8).map(([i,l,s,d])=>`<button data-a="sres" ${d}>${ic(i)}<span>${esc(l)}</span><small>${esc(s)}</small></button>`).join(''):`<p>No matches for "${esc(q)}" at ${esc(siteName(S.ui.site))}.</p>`;box.hidden=false;icons()}

